#!/bin/bash
# GLSL (generated by gen_conv_*.py) -> SPIR-V: glslang (Vulkan 1.3), entry rename, spirv-as 1.6.   usage: conv.sh in.comp ENTRY out.spv
set -e
glslangValidator -V --target-env vulkan1.3 "$1" -o /tmp/cv.g.spv >/dev/null
spirv-dis /tmp/cv.g.spv -o /tmp/cv.g.asm
sed -i "s/\"main\"/\"$2\"/" /tmp/cv.g.asm
spirv-as --target-env spv1.6 /tmp/cv.g.asm -o "$3"
spirv-val --target-env vulkan1.3 "$3"
